  --font-display: "Fraunces", "Playfair Display", Georgia, serif;
}

* { box-sizing: border-box; }
html { scroll-behavior: smooth; }
body {
  margin: 0;
  font-family: var(--font-sans);
  color: var(--ink);
  background: var(--bg);
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
}
img, svg { display: block; max-width: 100%; }

/* ---------- A11y helpers ---------- */
.skip-link {
  position: absolute;
  left: 8px;
  top: -100px;
  background: var(--ink);
  color: #fff;
  padding: 10px 14px;
  border-radius: 8px;
  z-index: 200;
  text-decoration: none;
}
.skip-link:focus { top: 8px; }
.sr-only {
  position: absolute !important;
  width: 1px; height: 1px;
  padding: 0; margin: -1px;
  overflow: hidden; clip: rect(0,0,0,0);
  white-space: nowrap; border: 0;
}

/* Focus styles — visible everywhere */
:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
  border-radius: 4px;
}

/* ---------- Layout ---------- */
.container {
  width: 100%;
  max-width: var(--maxw);
  margin: 0 auto;
  padding: 0 var(--gutter);
}

/* ---------- Top announcement ---------- */
.announce {
  background: var(--ink);
  color: #fff;
  text-align: center;
  font-size: 0.875rem;
  padding: 8px 12px;
}
.announce a { color: #fff; text-decoration: underline; }

/* ---------- Header ---------- */
.site-header {
  position: sticky;
  top: 0;
  z-index: 50;
  background: rgba(250,250,247,.92);
  backdrop-filter: saturate(140%) blur(8px);
  border-bottom: 1px solid var(--line);
}
.header-inner {
  display: grid;
  grid-template-columns: auto 1fr auto;
  align-items: center;
  gap: 16px;
  min-height: 72px;
}
.brand {
  font-family: var(--font-display);
  font-weight: 700;
  font-size: 1.5rem;
  letter-spacing: -0.01em;
  color: var(--ink);
  text-decoration: none;
}
.primary-nav ul {
  list-style: none;
  margin: 0; padding: 0;
  display: flex;
  gap: 28px;
  justify-content: center;
}
.primary-nav a {
  color: var(--ink-2);
  text-decoration: none;
  font-weight: 500;
  font-size: 0.95rem;
  padding: 6px 2px;
  border-bottom: 2px solid transparent;
}
.primary-nav a:hover { color: var(--ink); border-bottom-color: var(--ink); }

.header-actions {
  display: flex;
  align-items: center;
  gap: 6px;
}
.icon-btn {
  background: transparent;
  border: 1px solid transparent;
  width: 40px; height: 40px;
  border-radius: 999px;
  display: inline-flex;
  align-items: center; justify-content: center;
  cursor: pointer;
  color: var(--ink);
  position: relative;
}
.icon-btn:hover { background: var(--surface-2); }
.icon-btn svg { width: 20px; height: 20px; }
.cart-count {
  position: absolute;
  top: 4px; right: 4px;
  min-width: 18px; height: 18px;
  padding: 0 5px;
  background: var(--accent);
  color: #fff;
  font-size: 11px;
  font-weight: 700;
  border-radius: 999px;
  display: inline-flex;
  align-items: center; justify-content: center;
  border: 2px solid var(--bg);
}

/* mobile menu toggle */
.menu-toggle { display: none; }

@media (max-width: 820px) {
  .menu-toggle { display: inline-flex; }
  .primary-nav {
    position: absolute;
    left: 0; right: 0;
    top: 100%;
    background: var(--surface);
    border-bottom: 1px solid var(--line);
    display: none;
    padding: 12px 0;
  }
  .primary-nav.open { display: block; }
  .primary-nav ul {
    flex-direction: column;
    gap: 4px;
    padding: 0 var(--gutter);
  }
  .primary-nav a {
    display: block;
    padding: 12px 0;
    border-bottom: 1px solid var(--line);
  }
}

/* ---------- Buttons ---------- */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  font-family: inherit;
  font-weight: 600;
  font-size: 0.95rem;
  padding: 12px 22px;
  border-radius: 999px;
  text-decoration: none;
  cursor: pointer;
  border: 1px solid transparent;
  transition: background .15s ease, color .15s ease, border-color .15s ease;
}
.btn-primary {
  background: var(--ink);
  color: #fff;
}
.btn-primary:hover { background: var(--ink-2); }
.btn-secondary {
  background: transparent;
  color: var(--ink);
  border-color: var(--ink);
}
.btn-secondary:hover { background: var(--ink); color: #fff; }
.btn-ghost {
  background: transparent;
  color: var(--ink);
  padding: 8px 0;
  border-radius: 0;
  border-bottom: 2px solid var(--ink);
}
.btn-ghost:hover { color: var(--accent-ink); border-bottom-color: var(--accent-ink); }

/* ---------- Hero ---------- */
.hero {
  position: relative;
  margin-top: 12px;
}
.hero-grid {
  display: grid;
  grid-template-columns: 1.1fr .9fr;
  gap: clamp(20px, 3vw, 40px);
  align-items: stretch;
}
.hero-copy {
  background: var(--surface-2);
  border-radius: var(--radius-lg);
  padding: clamp(28px, 4vw, 56px);
  display: flex;
  flex-direction: column;
  justify-content: center;
}
.eyebrow {
  text-transform: uppercase;
  letter-spacing: .14em;
  font-size: 0.75rem;
  font-weight: 700;
  color: var(--accent-ink);
  margin: 0 0 14px;
}
.hero h1 {
  font-family: var(--font-display);
  font-weight: 600;
  font-size: clamp(2.25rem, 5vw, 3.75rem);
  line-height: 1.05;
  letter-spacing: -0.02em;
  margin: 0 0 16px;
}
.hero p {
  font-size: 1.0625rem;
  color: var(--ink-2);
  max-width: 46ch;
  margin: 0 0 28px;
}
.hero-actions {
  display: flex;
  gap: 12px;
  flex-wrap: wrap;
}
.hero-image {
  border-radius: var(--radius-lg);
  overflow: hidden;
  background: linear-gradient(135deg, #d8c8b6, #b69a7d);
  min-height: 380px;
  position: relative;
}
.hero-image::after {
  content: "";
  position: absolute; inset: 0;
  background:
    radial-gradient(circle at 30% 20%, rgba(255,255,255,.35), transparent 50%),
    radial-gradient(circle at 80% 70%, rgba(20,17,15,.18), transparent 60%);
}
.hero-image svg { width: 100%; height: 100%; }

@media (max-width: 820px) {
  .hero-grid { grid-template-columns: 1fr; }
  .hero-image { min-height: 260px; order: -1; }
}

/* ---------- Section structure ---------- */
section { padding: clamp(48px, 7vw, 96px) 0; }
.section-head {
  display: flex;
  align-items: end;
  justify-content: space-between;
  gap: 24px;
  margin-bottom: 32px;
  flex-wrap: wrap;
}
.section-head h2 {
  font-family: var(--font-display);
  font-weight: 600;
  font-size: clamp(1.75rem, 3vw, 2.5rem);
  letter-spacing: -0.01em;
  margin: 0;
  line-height: 1.1;
}
.section-head p {
  margin: 8px 0 0;
  color: var(--muted);
  max-width: 50ch;
}

/* ---------- Categories strip ---------- */
.categories {
  background: var(--surface);
  border-top: 1px solid var(--line);
  border-bottom: 1px solid var(--line);
  padding: 28px 0;
}
.cat-list {
  display: grid;
  grid-template-columns: repeat(6, 1fr);
  gap: 16px;
  list-style: none;
  margin: 0; padding: 0;
}
.cat-card {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
  padding: 14px 8px;
  border-radius: var(--radius);
  text-decoration: none;
  color: var(--ink);
  border: 1px solid transparent;
  text-align: center;
  font-size: 0.875rem;
  font-weight: 500;
}
.cat-card:hover { background: var(--surface-2); border-color: var(--line); }
.cat-icon {
  width: 48px; height: 48px;
  border-radius: 999px;
  background: var(--surface-2);
  display: inline-flex;
  align-items: center; justify-content: center;
  color: var(--ink);
}
.cat-icon svg { width: 24px; height: 24px; }

@media (max-width: 820px) {
  .cat-list { grid-template-columns: repeat(3, 1fr); }
}

/* ---------- Product grid ---------- */
.product-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 24px;
}
@media (max-width: 980px) { .product-grid { grid-template-columns: repeat(3, 1fr); } }
@media (max-width: 720px) { .product-grid { grid-template-columns: repeat(2, 1fr); } }

.product-card {
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  overflow: hidden;
  display: flex;
  flex-direction: column;
  transition: transform .15s ease, box-shadow .15s ease;
}
.product-card:hover { transform: translateY(-2px); box-shadow: var(--shadow-md); }

.product-media {
  position: relative;
  aspect-ratio: 1 / 1;
  background: var(--surface-2);
  overflow: hidden;
}
.product-media svg { width: 100%; height: 100%; }
.product-badge {
  position: absolute;
  top: 12px; left: 12px;
  background: var(--ink);
  color: #fff;
  font-size: 0.72rem;
  font-weight: 700;
  letter-spacing: .06em;
  text-transform: uppercase;
  padding: 5px 9px;
  border-radius: 999px;
}
.product-badge.sale { background: var(--sale); }
.product-badge.new { background: var(--accent); }

.wish-btn {
  position: absolute;
  top: 10px; right: 10px;
  width: 36px; height: 36px;
  border-radius: 999px;
  background: rgba(255,255,255,.9);
  border: 1px solid var(--line);
  display: inline-flex;
  align-items: center; justify-content: center;
  cursor: pointer;
  color: var(--ink-2);
}
.wish-btn:hover { background: #fff; color: var(--accent-ink); }
.wish-btn[aria-pressed="true"] { color: var(--accent); }
.wish-btn svg { width: 18px; height: 18px; }

.product-body {
  padding: 16px 16px 20px;
  display: flex;
  flex-direction: column;
  gap: 6px;
  flex: 1;
}
.product-cat {
  font-size: 0.75rem;
  text-transform: uppercase;
  letter-spacing: .1em;
  color: var(--muted);
}
.product-name {
  font-size: 1rem;
  font-weight: 600;
  margin: 0;
  color: var(--ink);
}
.product-name a { color: inherit; text-decoration: none; }
.product-name a:hover { text-decoration: underline; }
.product-rating {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: 0.8125rem;
  color: var(--ink-2);
}
.product-rating svg { width: 14px; height: 14px; color: #b97f12; }
.product-price {
  margin-top: auto;
  display: flex;
  align-items: baseline;
  gap: 8px;
  padding-top: 8px;
}
.price-now { font-weight: 700; font-size: 1.05rem; }
.price-was {
  color: var(--muted);
  text-decoration: line-through;
  font-size: 0.9rem;
}
.add-cart {
  margin-top: 12px;
  width: 100%;
  padding: 10px 12px;
  font-size: 0.9rem;
}

/* ---------- Deals ---------- */
.deals { background: var(--surface); }
.deals-grid {
  display: grid;
  grid-template-columns: 1.4fr 1fr 1fr;
  gap: 20px;
}
.deal-card {
  position: relative;
  border-radius: var(--radius-lg);
  overflow: hidden;
  min-height: 260px;
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
  padding: 28px;
  color: #fff;
  text-decoration: none;
  isolation: isolate;
}
.deal-card::before {
  content: "";
  position: absolute; inset: 0;
  background: var(--bg-grad, linear-gradient(135deg, #2b2622, #56463b));
  z-index: -2;
}
.deal-card::after {
  content: "";
  position: absolute; inset: 0;
  background: linear-gradient(180deg, rgba(0,0,0,0) 30%, rgba(0,0,0,.55) 100%);
  z-index: -1;
}
.deal-card:hover .deal-arrow { transform: translateX(4px); }
.deal-card .eyebrow {
  color: #fff;
  opacity: .9;
}
.deal-card h3 {
  font-family: var(--font-display);
  font-weight: 600;
  font-size: clamp(1.5rem, 2.5vw, 2rem);
  line-height: 1.1;
  margin: 6px 0 8px;
}
.deal-card p {
  margin: 0 0 14px;
  font-size: 0.95rem;
  opacity: .92;
  max-width: 32ch;
}
.deal-link {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-weight: 600;
  font-size: 0.95rem;
  border-bottom: 1px solid #fff;
  padding-bottom: 2px;
  width: fit-content;
}
.deal-arrow { transition: transform .2s ease; }

.deal-card.large { --bg-grad: linear-gradient(135deg, #2b1d16, #6b3a22); grid-row: span 2; min-height: 540px; }
.deal-card.b { --bg-grad: linear-gradient(135deg, #1f3a3a, #3f7676); }
.deal-card.c { --bg-grad: linear-gradient(135deg, #3b2b3a, #76505d); }

@media (max-width: 820px) {
  .deals-grid { grid-template-columns: 1fr; }
  .deal-card.large { grid-row: auto; min-height: 320px; }
}

/* ---------- Editorial ---------- */
.editorial-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 28px;
}
@media (max-width: 820px) { .editorial-grid { grid-template-columns: 1fr; } }

.article-card {
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  overflow: hidden;
  display: flex;
  flex-direction: column;
  transition: box-shadow .15s ease;
}
.article-card:hover { box-shadow: var(--shadow-md); }
.article-media {
  aspect-ratio: 4 / 3;
  background: var(--surface-2);
}
.article-media svg { width: 100%; height: 100%; }
.article-body { padding: 22px 22px 26px; }
.article-meta {
  font-size: 0.75rem;
  text-transform: uppercase;
  letter-spacing: .12em;
  color: var(--accent-ink);
  font-weight: 700;
  margin-bottom: 8px;
}
.article-card h3 {
  font-family: var(--font-display);
  font-weight: 600;
  font-size: 1.35rem;
  line-height: 1.25;
  margin: 0 0 10px;
}
.article-card h3 a { color: var(--ink); text-decoration: none; }
.article-card h3 a:hover { text-decoration: underline; }
.article-excerpt { color: var(--ink-2); margin: 0 0 14px; font-size: 0.95rem; }
.read-more {
  font-weight: 600;
  color: var(--accent-ink);
  text-decoration: none;
  border-bottom: 1px solid currentColor;
  padding-bottom: 1px;
}
.read-more:hover { color: var(--ink); }

/* ---------- Newsletter ---------- */
.newsletter {
  background: var(--ink);
  color: #fff;
}
.newsletter-inner {
  display: grid;
  grid-template-columns: 1.1fr 1fr;
  gap: 40px;
  align-items: center;
}
.newsletter h2 {
  font-family: var(--font-display);
  font-weight: 600;
  font-size: clamp(1.75rem, 3vw, 2.4rem);
  margin: 0 0 12px;
  line-height: 1.1;
}
.newsletter p { color: #d9d4cc; margin: 0; max-width: 48ch; }

.signup-form {
  display: flex;
  flex-direction: column;
  gap: 10px;
}
.signup-row {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
}
.signup-row label { display: block; flex: 1 1 220px; min-width: 0; }
.signup-row .field-label {
  font-size: 0.875rem;
  font-weight: 500;
  margin-bottom: 6px;
  color: #fff;
}
.signup-row .req { color: #ffb4a8; margin-left: 2px; }
.signup-row input {
  width: 100%;
  padding: 12px 14px;
  border-radius: 999px;
  border: 1px solid #5a534b;
  background: #1f1b18;
  color: #fff;
  font-size: 0.95rem;
  font-family: inherit;
}
.signup-row input::placeholder { color: #9b948c; }
.signup-row input:focus-visible {
  outline: 3px solid #ffd76b;
  outline-offset: 2px;
  border-color: #ffd76b;
}
.signup-row input[aria-invalid="true"] {
  border-color: #ffb4a8;
}
.signup-row button {
  padding: 12px 24px;
  border-radius: 999px;
  border: 0;
  background: #fff;
  color: var(--ink);
  font-weight: 700;
  cursor: pointer;
  font-family: inherit;
  font-size: 0.95rem;
}
.signup-row button:hover { background: #ffd76b; }
.field-error {
  color: #ffb4a8;
  font-size: 0.85rem;
  margin-top: 4px;
  min-height: 1em;
}
.form-status {
  font-size: 0.9rem;
  color: #d9d4cc;
  min-height: 1.2em;
}
.form-status.success { color: #b6e8c7; }

@media (max-width: 820px) {
  .newsletter-inner { grid-template-columns: 1fr; }
}

/* ---------- Footer ---------- */
.site-footer {
  background: var(--surface);
  border-top: 1px solid var(--line);
  padding: 56px 0 24px;
}
.footer-grid {
  display: grid;
  grid-template-columns: 1.4fr repeat(3, 1fr);
  gap: 32px;
}
@media (max-width: 820px) { .footer-grid { grid-template-columns: 1fr 1fr; } }
.footer-col h4 {
  font-size: 0.875rem;
  text-transform: uppercase;
  letter-spacing: .1em;
  margin: 0 0 16px;
  color: var(--ink);
}
.footer-col ul { list-style: none; padding: 0; margin: 0; display: grid; gap: 10px; }
.footer-col a { color: var(--ink-2); text-decoration: none; font-size: 0.95rem; }
.footer-col a:hover { color: var(--ink); text-decoration: underline; }
.footer-brand .brand { font-size: 1.5rem; }
.footer-brand p { color: var(--muted); margin: 12px 0 16px; max-width: 36ch; }
.social {
  display: flex; gap: 8px;
}
.social a {
  width: 36px; height: 36px;
  border-radius: 999px;
  border: 1px solid var(--line);
  display: inline-flex;
  align-items: center; justify-content: center;
  color: var(--ink);
}
.social a:hover { background: var(--ink); color: #fff; border-color: var(--ink); }
.social svg { width: 18px; height: 18px; }
.footer-bottom {
  margin-top: 40px;
  padding-top: 20px;
  border-top: 1px solid var(--line);
  display: flex;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 12px;
  font-size: 0.85rem;
  color: var(--muted);
}

/* ---------- Toast / live region ---------- */
.toast {
  position: fixed;
  bottom: 24px;
  left: 50%;
  transform: translateX(-50%) translateY(20px);
  background: var(--ink);
  color: #fff;
  padding: 12px 20px;
  border-radius: 999px;
  font-size: 0.9rem;
  box-shadow: var(--shadow-md);
  opacity: 0;
  pointer-events: none;
  transition: opacity .2s ease, transform .2s ease;
  z-index: 100;
}
.toast.show { opacity: 1; transform: translateX(-50%) translateY(0); }

/* ---------- Reduced motion ---------- */
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    transition: none !important;
    animation: none !important;
    scroll-behavior: auto !important;
  }
}

/* ---------- Forced colors ---------- */
@media (forced-colors: active) {
  .btn-primary, .btn-secondary, .deal-card, .product-card, .article-card {
    border: 1px solid ButtonBorder;
  }
  .icon-btn, .wish-btn, .signup-row button { border: 1px solid ButtonBorder; }
  :focus-visible { outline-color: Highlight; }
}

