    case "bag": return (<svg {...common}><path d="M5 8h14l-1.2 11.1A2 2 0 0 1 15.8 21H8.2a2 2 0 0 1-2-1.9L5 8z"/><path d="M9 8V6a3 3 0 0 1 6 0v2"/></svg>);
    case "menu": return (<svg {...common}><path d="M4 7h16M4 12h16M4 17h16"/></svg>);
    case "close": return (<svg {...common}><path d="M6 6l12 12M18 6 6 18"/></svg>);
    case "arrow": return (<svg {...common}><path d="M5 12h14M13 6l6 6-6 6"/></svg>);
    case "star": return (<svg {...common} fill="currentColor" stroke="none"><path d="M12 2.5l3 6.2 6.8.9-4.9 4.7 1.2 6.7L12 17.8l-6.1 3.2L7.1 14.3 2.2 9.6l6.8-.9z"/></svg>);
    case "tee": return (<svg viewBox="0 0 24 24" fill="currentColor" aria-hidden="true"><path d="M8 3 4 6l2 4 2-1v12h8V9l2 1 2-4-4-3-2 2h-4z"/></svg>);
    case "shoe": return (<svg viewBox="0 0 24 24" fill="currentColor" aria-hidden="true"><path d="M3 16c0-2 2-3 4-3l3-4c1-1 3-1 4 0l1 2 5 2c2 .5 2 3-0.5 4H4a1 1 0 0 1-1-1z"/></svg>);
    case "bagcat": return (<svg viewBox="0 0 24 24" fill="currentColor" aria-hidden="true"><path d="M6 7h12l-1 13H7L6 7zm3 0a3 3 0 0 1 6 0"/></svg>);
    case "watch": return (<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2"><circle cx="12" cy="12" r="5"/><path d="M9 7l1-3h4l1 3M9 17l1 3h4l1-3"/></svg>);
    case "home": return (<svg viewBox="0 0 24 24" fill="currentColor" aria-hidden="true"><path d="M3 11 12 3l9 8v9h-6v-6h-6v6H3z"/></svg>);
    case "gift": return (<svg viewBox="0 0 24 24" fill="currentColor" aria-hidden="true"><path d="M3 9h18v3H3zM4 13h16v8H4zM12 9V6m-3 0a2 2 0 1 1 3-1 2 2 0 1 1 3 1"/></svg>);
    case "ig": return (<svg {...common}><rect x="3" y="3" width="18" height="18" rx="5"/><circle cx="12" cy="12" r="4"/><circle cx="17.5" cy="6.5" r="1" fill="currentColor"/></svg>);
    case "tw": return (<svg {...common}><path d="M22 5.8a8 8 0 0 1-2.4.7 4 4 0 0 0 1.8-2.2 8 8 0 0 1-2.6 1A4 4 0 0 0 12 9a11 11 0 0 1-8-4s-4 9 5 13a12 12 0 0 1-7 2c9 5 20 0 20-11.5 0-.3 0-.6-.1-.8A6 6 0 0 0 22 5.8z"/></svg>);
    case "fb": return (<svg {...common}><path d="M14 22v-9h3l1-4h-4V6.5c0-1.2.4-2 2-2h2V1h-3c-3 0-5 1.8-5 5V9H7v4h3v9z" fill="currentColor" stroke="none"/></svg>);
    default: return null;
  }
};

/* ---------- Decorative product illustrations ---------- */
const ProductArt = ({ variant }) => {
  const palettes = {
    a: ["#e9dfd1", "#b6906a", "#3b2a1d"],
    b: ["#dfe6e3", "#7aa39a", "#1e2f2c"],
    c: ["#f1e2d6", "#d18b5b", "#4d2a16"],
    d: ["#e6e2dc", "#9a877a", "#2c2620"],
    e: ["#efe7df", "#c89b6e", "#3a2418"],
    f: ["#dfe1ea", "#7882a3", "#1c2236"],
    g: ["#ecead3", "#a8a76f", "#3b3a1e"],
    h: ["#f3dfdb", "#c47c70", "#3a1d18"],
  };
  const [bg, mid, dark] = palettes[variant] || palettes.a;

  const shapes = {
    a: <><circle cx="100" cy="110" r="55" fill={mid}/><rect x="80" y="100" width="40" height="70" rx="8" fill={dark}/></>,
    b: <><rect x="55" y="60" width="90" height="100" rx="14" fill={mid}/><rect x="70" y="80" width="60" height="14" fill={dark}/><rect x="70" y="110" width="40" height="10" fill={bg}/></>,
    c: <><ellipse cx="100" cy="130" rx="65" ry="22" fill={mid}/><path d="M55 130 C 55 80, 145 80, 145 130 Z" fill={dark}/></>,
    d: <><circle cx="100" cy="100" r="60" fill={mid}/><circle cx="100" cy="100" r="34" fill={bg}/><circle cx="100" cy="100" r="10" fill={dark}/></>,
    e: <><path d="M60 60 L140 60 L130 170 L70 170 Z" fill={mid}/><rect x="80" y="80" width="40" height="6" fill={dark}/></>,
    f: <><rect x="50" y="80" width="100" height="60" rx="10" fill={mid}/><rect x="60" y="92" width="80" height="10" fill={dark}/><rect x="60" y="110" width="50" height="8" fill={bg}/></>,
    g: <><path d="M100 40 L140 160 L60 160 Z" fill={mid}/><circle cx="100" cy="120" r="14" fill={dark}/></>,
    h: <><circle cx="80" cy="110" r="30" fill={mid}/><circle cx="125" cy="110" r="30" fill={dark}/></>,
  };

  return (
    <svg viewBox="0 0 200 200" preserveAspectRatio="xMidYMid slice" aria-hidden="true" focusable="false">
      <rect width="200" height="200" fill={bg}/>
      {shapes[variant] || shapes.a}
    </svg>
  );
};

/* ---------- Header ---------- */
const Header = ({ cartCount, onCartClick }) => {
  const [open, setOpen] = useState(false);
  const links = [
    { href: "#new", label: "New In" },
    { href: "#featured", label: "Shop" },
    { href: "#deals", label: "Sale" },
    { href: "#editorial", label: "Journal" },
    { href: "#about", label: "About" },
  ];
  return (
    <header className="site-header">
      <div className="container header-inner">
        <a href="#top" className="brand" aria-label="Maison Rove home">Maison Rove</a>
        <nav id="primary-nav" className={`primary-nav${open ? " open" : ""}`} aria-label="Primary">
          <ul>
            {links.map(l => (
              <li key={l.href}><a href={l.href} onClick={() => setOpen(false)}>{l.label}</a></li>
            ))}
          </ul>
        </nav>
        <div className="header-actions">
          <button className="icon-btn" type="button" aria-label="Search">
            <Icon name="search"/>
          </button>
          <button className="icon-btn" type="button" aria-label="Account">
            <Icon name="user"/>
          </button>
          <button className="icon-btn" type="button" aria-label="Wishlist">
            <Icon name="heart"/>
          </button>
          <button className="icon-btn" type="button" aria-label={`Cart, ${cartCount} item${cartCount === 1 ? "" : "s"}`} onClick={onCartClick}>
            <Icon name="bag"/>
            {cartCount > 0 && <span className="cart-count" aria-hidden="true">{cartCount}</span>}
          </button>
          <button
            className="icon-btn menu-toggle"
            type="button"
            aria-label={open ? "Close menu" : "Open menu"}
            aria-expanded={open}
            aria-controls="primary-nav"
            onClick={() => setOpen(o => !o)}
          >
            <Icon name={open ? "close" : "menu"}/>
          </button>
        </div>
      </div>
    </header>
  );
};

/* ---------- Hero ---------- */
const Hero = () => (
  <section className="hero" aria-labelledby="hero-title" id="top">
    <div className="container hero-grid">
      <div className="hero-copy">
        <p className="eyebrow">Spring / Summer 2026</p>
        <h1 id="hero-title">Quiet pieces, made to roam.</h1>
        <p>Considered essentials in natural fibres and warm neutrals — designed in Lisbon, made to last.</p>
        <div className="hero-actions">
          <a href="#featured" className="btn btn-primary">Shop the collection <Icon name="arrow"/></a>
          <a href="#editorial" className="btn btn-secondary">Read the journal</a>
        </div>
      </div>
      <div className="hero-image" role="img" aria-label="Stylised illustration of a linen tote, ceramic mug and folded knit on a warm sand backdrop.">
        <svg viewBox="0 0 600 500" preserveAspectRatio="xMidYMid slice" aria-hidden="true" focusable="false">
          <defs>
            <linearGradient id="hg" x1="0" x2="1" y1="0" y2="1">
              <stop offset="0" stopColor="#d8c8b6"/>
              <stop offset="1" stopColor="#a07e5e"/>
            </linearGradient>
          </defs>
          <rect width="600" height="500" fill="url(#hg)"/>
          <ellipse cx="300" cy="430" rx="240" ry="22" fill="rgba(0,0,0,.18)"/>
          <rect x="160" y="160" width="200" height="240" rx="14" fill="#f1e6d4"/>
          <path d="M200 160 Q 260 100 320 160" stroke="#3b2a1d" strokeWidth="6" fill="none"/>
          <circle cx="430" cy="320" r="70" fill="#c47c5a"/>
          <rect x="490" y="290" width="40" height="60" rx="6" fill="#c47c5a"/>
          <rect x="380" y="380" width="180" height="30" rx="6" fill="#6d4a32"/>
        </svg>
      </div>
    </div>
  </section>
);

/* ---------- Categories ---------- */
const categories = [
  { id: "tops", label: "Tops", icon: "tee" },
  { id: "shoes", label: "Footwear", icon: "shoe" },
  { id: "bags", label: "Bags", icon: "bagcat" },
  { id: "access", label: "Accessories", icon: "watch" },
  { id: "home", label: "Home", icon: "home" },
  { id: "gifts", label: "Gifts", icon: "gift" },
];
const Categories = () => (
  <section className="categories" aria-label="Shop by category">
    <div className="container">
      <ul className="cat-list">
        {categories.map(c => (
          <li key={c.id}>
            <a className="cat-card" href={`#cat-${c.id}`}>
              <span className="cat-icon" aria-hidden="true"><Icon name={c.icon}/></span>
              <span>{c.label}</span>
            </a>
          </li>
        ))}
      </ul>
    </div>
  </section>
);

/* ---------- Product Card ---------- */
const StarRow = ({ rating, count }) => (
  <span className="product-rating" aria-label={`Rated ${rating} out of 5 from ${count} reviews`}>
    <span aria-hidden="true" style={{ display: "inline-flex", gap: 1 }}>
      {[1,2,3,4,5].map(i => (
        <Icon key={i} name="star" style={{ opacity: i <= Math.round(rating) ? 1 : 0.25 }}/>
      ))}
    </span>
    <span aria-hidden="true">({count})</span>
  </span>
);

const ProductCard = ({ product, onAdd, isWished, onWish }) => {
  const onSale = product.priceWas && product.priceWas > product.price;
  const badge = product.badge || (onSale ? "Sale" : null);
  const badgeClass = badge === "Sale" ? "sale" : badge === "New" ? "new" : "";
  return (
    <article className="product-card">
      <div className="product-media">
        <ProductArt variant={product.art}/>
        {badge && <span className={`product-badge ${badgeClass}`}>{badge}</span>}
        <button
          type="button"
          className="wish-btn"
          aria-pressed={isWished}
          aria-label={`${isWished ? "Remove" : "Add"} ${product.name} ${isWished ? "from" : "to"} wishlist`}
          onClick={() => onWish(product.id)}
        >
          <Icon name="heart"/>
        </button>
      </div>
      <div className="product-body">
        <span className="product-cat">{product.category}</span>
        <h3 className="product-name"><a href={`#product-${product.id}`}>{product.name}</a></h3>
        <StarRow rating={product.rating} count={product.reviews}/>
        <div className="product-price">
          <span className="price-now" aria-label={`Price ${product.price.toFixed(2)} dollars`}>${product.price.toFixed(2)}</span>
          {onSale && (
            <span className="price-was" aria-label={`Original price ${product.priceWas.toFixed(2)} dollars`}>${product.priceWas.toFixed(2)}</span>
          )}
        </div>
        <button type="button" className="btn btn-primary add-cart" onClick={() => onAdd(product)}>
          Add to bag
        </button>
      </div>
    </article>
  );
};

/* ---------- Featured grid ---------- */
const products = [
  { id: 1, name: "Linen Field Shirt", category: "Tops", price: 128, rating: 4.6, reviews: 142, badge: "New", art: "b" },
  { id: 2, name: "Roma Leather Loafer", category: "Footwear", price: 245, priceWas: 320, rating: 4.8, reviews: 89, art: "c" },
  { id: 3, name: "Canvas Market Tote", category: "Bags", price: 89, rating: 4.7, reviews: 312, art: "e" },
  { id: 4, name: "Merino Crew Knit", category: "Tops", price: 165, rating: 4.5, reviews: 76, badge: "Bestseller", art: "g" },
  { id: 5, name: "Atelier Wrist Watch", category: "Accessories", price: 320, priceWas: 380, rating: 4.9, reviews: 54, art: "d" },
  { id: 6, name: "Sienna Suede Sneaker", category: "Footwear", price: 195, rating: 4.4, reviews: 207, badge: "New", art: "h" },
  { id: 7, name: "Stoneware Mug Set", category: "Home", price: 64, rating: 4.8, reviews: 421, art: "a" },
  { id: 8, name: "Travel Card Wallet", category: "Accessories", price: 78, priceWas: 95, rating: 4.6, reviews: 138, art: "f" },
];

const Featured = ({ onAdd, wishlist, onWish }) => (
  <section id="featured" aria-labelledby="featured-title">
    <div className="container">
      <div className="section-head">
        <div>
          <h2 id="featured-title">Featured this season</h2>
          <p>A tightly edited rotation of the pieces our team is reaching for right now.</p>
        </div>
        <a href="#shop-all" className="btn btn-ghost">View all <Icon name="arrow"/></a>
      </div>
      <div className="product-grid">
        {products.map(p => (
          <ProductCard key={p.id} product={p} onAdd={onAdd} isWished={wishlist.has(p.id)} onWish={onWish}/>
        ))}
      </div>
    </div>
  </section>
);

/* ---------- Deals ---------- */
const deals = [
  { id: "d1", className: "large", eyebrow: "Mid-season event", title: "Up to 40% off select knits", desc: "A curated selection of merino and cashmere — while quantities last.", href: "#deal-knits" },
  { id: "d2", className: "b", eyebrow: "Last chance", title: "Final cut footwear", desc: "Closing sizes from the spring drop.", href: "#deal-shoes" },
  { id: "d3", className: "c", eyebrow: "Bundle & save", title: "Two totes, one price", desc: "Add any two canvas totes — second is on us.", href: "#deal-totes" },
];

const Deals = () => (
  <section id="deals" className="deals" aria-labelledby="deals-title">
    <div className="container">
      <div className="section-head">
        <div>
          <h2 id="deals-title">This week's deals</h2>
          <p>Limited offers refreshed every Monday — no codes required at checkout.</p>
        </div>
      </div>
      <div className="deals-grid">
        {deals.map(d => (
          <a key={d.id} className={`deal-card ${d.className}`} href={d.href}>
            <p className="eyebrow">{d.eyebrow}</p>
            <h3>{d.title}</h3>
            <p>{d.desc}</p>
            <span className="deal-link">Shop now <span className="deal-arrow" aria-hidden="true"><Icon name="arrow"/></span></span>
          </a>
        ))}
      </div>
    </div>
  </section>
);

/* ---------- Editorial ---------- */
const articles = [
  { id: "a1", category: "Field Notes", title: "A summer in the Algarve, packed in a single tote", excerpt: "Our buying director on the seven pieces that travelled with her along the southern coast.", art: "e" },
  { id: "a2", category: "Makers", title: "Inside the family workshop behind our loafers", excerpt: "Three generations of last-makers in a quiet town outside Florence.", art: "c" },
  { id: "a3", category: "Care Guide", title: "How to keep linen looking better with age", excerpt: "Five small habits that turn a new shirt into a lifelong piece.", art: "b" },
];

const Editorial = () => (
  <section id="editorial" aria-labelledby="editorial-title">
    <div className="container">
      <div className="section-head">
        <div>
          <h2 id="editorial-title">From the journal</h2>
          <p>Stories about the things we make and the people behind them.</p>
        </div>
        <a href="#all-stories" className="btn btn-ghost">All stories <Icon name="arrow"/></a>
      </div>
      <div className="editorial-grid">
        {articles.map(a => (
          <article key={a.id} className="article-card">
            <div className="article-media" role="img" aria-label={`Editorial illustration for ${a.title}`}>
              <ProductArt variant={a.art}/>
            </div>
            <div className="article-body">
              <p className="article-meta">{a.category}</p>
              <h3><a href={`#story-${a.id}`}>{a.title}</a></h3>
              <p className="article-excerpt">{a.excerpt}</p>
              <a href={`#story-${a.id}`} className="read-more">Read story</a>
            </div>
          </article>
        ))}
      </div>
    </div>
  </section>
);

/* ---------- Newsletter ---------- */
const Newsletter = ({ onToast }) => {
  const [email, setEmail] = useState("");
  const [error, setError] = useState("");
  const [status, setStatus] = useState("");
  const inputRef = useRef(null);

  const onSubmit = (e) => {
    e.preventDefault();
    const value = email.trim();
    if (!value) {
      setError("Please enter your email address.");
      setStatus("");
      inputRef.current?.focus();
      return;
    }
    if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value)) {
      setError("Please enter a valid email address, like name@example.com.");
      setStatus("");
      inputRef.current?.focus();
      return;
    }
    setError("");
    setStatus("Thank you — please check your inbox to confirm.");
    setEmail("");
    onToast("Subscribed. Welcome to Maison Rove.");
  };

  return (
    <section className="newsletter" aria-labelledby="news-title">
      <div className="container newsletter-inner">
        <div>
          <h2 id="news-title">Letters from Lisbon</h2>
          <p>New arrivals, behind-the-scenes notes, and early access to seasonal events. One short email, every other Friday.</p>
        </div>
        <form className="signup-form" noValidate onSubmit={onSubmit} aria-describedby="news-status">
          <div className="signup-row">
            <label htmlFor="news-email">
              <span className="field-label">Email address<span className="req" aria-hidden="true">*</span></span>
              <input
                id="news-email"
                ref={inputRef}
                type="email"
                inputMode="email"
                autoComplete="email"
                placeholder="name@example.com"
                value={email}
                required
                aria-required="true"
                aria-invalid={error ? "true" : "false"}
                aria-describedby="news-error"
                onChange={e => setEmail(e.target.value)}
              />
            </label>
            <button type="submit">Subscribe</button>
          </div>
          <p id="news-error" className="field-error" role="alert">{error}</p>
          <p id="news-status" className={`form-status${status ? " success" : ""}`} aria-live="polite">{status}</p>
        </form>
      </div>
    </section>
  );
};

/* ---------- Footer ---------- */
const Footer = () => (
  <footer className="site-footer" id="about">
    <div className="container">
      <div className="footer-grid">
        <div className="footer-col footer-brand">
          <span className="brand">Maison Rove</span>
          <p>Considered essentials, designed in Lisbon and made by small workshops across Portugal and Italy.</p>
          <div className="social" aria-label="Social media">
            <a href="#instagram" aria-label="Maison Rove on Instagram"><Icon name="ig"/></a>
            <a href="#twitter" aria-label="Maison Rove on Twitter"><Icon name="tw"/></a>
            <a href="#facebook" aria-label="Maison Rove on Facebook"><Icon name="fb"/></a>
          </div>
        </div>
        <div className="footer-col">
          <h4>Shop</h4>
          <ul>
            <li><a href="#new">New in</a></li>
            <li><a href="#bestsellers">Bestsellers</a></li>
            <li><a href="#deals">Sale</a></li>
            <li><a href="#gifts">Gift cards</a></li>
          </ul>
        </div>
        <div className="footer-col">
          <h4>Help</h4>
          <ul>
            <li><a href="#contact">Contact us</a></li>
            <li><a href="#shipping">Shipping &amp; returns</a></li>
            <li><a href="#size">Size guide</a></li>
            <li><a href="#faq">FAQ</a></li>
          </ul>
        </div>
        <div className="footer-col">
          <h4>Company</h4>
          <ul>
            <li><a href="#story">Our story</a></li>
            <li><a href="#sustain">Sustainability</a></li>
            <li><a href="#stores">Stores</a></li>
            <li><a href="#careers">Careers</a></li>
          </ul>
        </div>
      </div>
      <div className="footer-bottom">
        <span>© 2026 Maison Rove. All rights reserved.</span>
        <span><a href="#privacy" style={{ color: "inherit" }}>Privacy</a> · <a href="#terms" style={{ color: "inherit" }}>Terms</a> · <a href="#accessibility" style={{ color: "inherit" }}>Accessibility</a></span>
      </div>
    </div>
  </footer>
);

/* ---------- Toast (live region) ---------- */
const Toast = ({ message }) => (
  <div className={`toast${message ? " show" : ""}`} role="status" aria-live="polite">{message}</div>
);

/* ---------- App ---------- */
const App = () => {
  const [cart, setCart] = useState([]);
  const [wishlist, setWishlist] = useState(new Set());
  const [toast, setToast] = useState("");
  const toastTimer = useRef(null);

  const showToast = useCallback((msg) => {
    setToast(msg);
    clearTimeout(toastTimer.current);
    toastTimer.current = setTimeout(() => setToast(""), 2400);
  }, []);

  const addToCart = useCallback((p) => {
    setCart(c => [...c, p.id]);
    showToast(`Added “${p.name}” to bag`);
  }, [showToast]);

  const toggleWish = useCallback((id) => {
    setWishlist(w => {
      const next = new Set(w);
      next.has(id) ? next.delete(id) : next.add(id);
      return next;
    });
  }, []);

  const cartCount = cart.length;

  return (
    <Fragment>
      <a href="#main" className="skip-link">Skip to main content</a>
      <div className="announce" role="region" aria-label="Promotion">
        Free carbon-neutral shipping on orders over $120. <a href="#shipping">Details</a>
      </div>
      <Header cartCount={cartCount} onCartClick={() => showToast(cartCount ? `${cartCount} item${cartCount === 1 ? "" : "s"} in your bag` : "Your bag is empty")}/>
      <main id="main">
        <Hero/>
        <Categories/>
        <Featured onAdd={addToCart} wishlist={wishlist} onWish={toggleWish}/>
        <Deals/>
        <Editorial/>
        <Newsletter onToast={showToast}/>
      </main>
      <Footer/>
      <Toast message={toast}/>
    </Fragment>
  );
};

ReactDOM.createRoot(document.getElementById("root")).render(<App/>);
