/* ---------- Product Card ---------- */
const StarRow = ({ rating, count }) => (
  <span className="product-rating" aria-label={`Rated ${rating} out of 5 from ${count} reviews`}>
    <span aria-hidden="true" style={{ display: "inline-flex", gap: 1 }}>
      {[1,2,3,4,5].map(i => (
        <Icon key={i} name="star" style={{ opacity: i <= Math.round(rating) ? 1 : 0.25 }}/>
      ))}
    </span>
    <span aria-hidden="true">({count})</span>
  </span>
);

const ProductCard = ({ product, onAdd, isWished, onWish }) => {
  const onSale = product.priceWas && product.priceWas > product.price;
  const badge = product.badge || (onSale ? "Sale" : null);
  const badgeClass = badge === "Sale" ? "sale" : badge === "New" ? "new" : "";
  return (
    <article className="product-card">
      <div className="product-media">
        <ProductArt variant={product.art}/>
        {badge && <span className={`product-badge ${badgeClass}`}>{badge}</span>}
        <button
          type="button"
          className="wish-btn"
          aria-pressed={isWished}
          aria-label={`${isWished ? "Remove" : "Add"} ${product.name} ${isWished ? "from" : "to"} wishlist`}
          onClick={() => onWish(product.id)}
        >
          <Icon name="heart"/>
        </button>
      </div>
      <div className="product-body">
        <span className="product-cat">{product.category}</span>
        <h3 className="product-name"><a href={`#product-${product.id}`}>{product.name}</a></h3>
        <StarRow rating={product.rating} count={product.reviews}/>
        <div className="product-price">
          <span className="price-now" aria-label={`Price ${product.price.toFixed(2)} dollars`}>${product.price.toFixed(2)}</span>
          {onSale && (
            <span className="price-was" aria-label={`Original price ${product.priceWas.toFixed(2)} dollars`}>${product.priceWas.toFixed(2)}</span>
          )}
        </div>
        <button type="button" className="btn btn-primary add-cart" onClick={() => onAdd(product)}>
          Add to bag
        </button>
      </div>
    </article>
  );
};

