/* ---------- Newsletter ---------- */
const Newsletter = ({ onToast }) => {
  const [email, setEmail] = useState("");
  const [error, setError] = useState("");
  const [status, setStatus] = useState("");
  const inputRef = useRef(null);

  const onSubmit = (e) => {
    e.preventDefault();
    const value = email.trim();
    if (!value) {
      setError("Please enter your email address.");
      setStatus("");
      inputRef.current?.focus();
      return;
    }
    if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value)) {
      setError("Please enter a valid email address, like name@example.com.");
      setStatus("");
      inputRef.current?.focus();
      return;
    }
    setError("");
    setStatus("Thank you — please check your inbox to confirm.");
    setEmail("");
    onToast("Subscribed. Welcome to Maison Rove.");
  };

  return (
    <section className="newsletter" aria-labelledby="news-title">
      <div className="container newsletter-inner">
        <div>
          <h2 id="news-title">Letters from Lisbon</h2>
          <p>New arrivals, behind-the-scenes notes, and early access to seasonal events. One short email, every other Friday.</p>
        </div>
        <form className="signup-form" noValidate onSubmit={onSubmit} aria-describedby="news-status">
          <div className="signup-row">
            <label htmlFor="news-email">
              <span className="field-label">Email address<span className="req" aria-hidden="true">*</span></span>
              <input
                id="news-email"
                ref={inputRef}
                type="email"
                inputMode="email"
                autoComplete="email"
                placeholder="name@example.com"
                value={email}
                required
                aria-required="true"
                aria-invalid={error ? "true" : "false"}
                aria-describedby="news-error"
                onChange={e => setEmail(e.target.value)}
              />
            </label>
            <button type="submit">Subscribe</button>
          </div>
          <p id="news-error" className="field-error" role="alert">{error}</p>
          <p id="news-status" className={`form-status${status ? " success" : ""}`} aria-live="polite">{status}</p>
        </form>
      </div>
    </section>
  );
};

