/* ---------- Toast (live region) ---------- */
const Toast = ({ message }) => (
  <div className={`toast${message ? " show" : ""}`} role="status" aria-live="polite">{message}</div>
);

/* ---------- App ---------- */
const App = () => {
  const [cart, setCart] = useState([]);
  const [wishlist, setWishlist] = useState(new Set());
  const [toast, setToast] = useState("");
  const toastTimer = useRef(null);

  const showToast = useCallback((msg) => {
    setToast(msg);
    clearTimeout(toastTimer.current);
    toastTimer.current = setTimeout(() => setToast(""), 2400);
  }, []);

  const addToCart = useCallback((p) => {
    setCart(c => [...c, p.id]);
    showToast(`Added “${p.name}” to bag`);
  }, [showToast]);

  const toggleWish = useCallback((id) => {
    setWishlist(w => {
      const next = new Set(w);
      next.has(id) ? next.delete(id) : next.add(id);
      return next;
    });
  }, []);

  const cartCount = cart.length;

  return (
    <Fragment>
      <a href="#main" className="skip-link">Skip to main content</a>
      <div className="announce" role="region" aria-label="Promotion">
        Free carbon-neutral shipping on orders over $120. <a href="#shipping">Details</a>
      </div>
      <Header cartCount={cartCount} onCartClick={() => showToast(cartCount ? `${cartCount} item${cartCount === 1 ? "" : "s"} in your bag` : "Your bag is empty")}/>
      <main id="main">
        <Hero/>
        <Categories/>
        <Featured onAdd={addToCart} wishlist={wishlist} onWish={toggleWish}/>
        <Deals/>
        <Editorial/>
        <Newsletter onToast={showToast}/>
      </main>
      <Footer/>
      <Toast message={toast}/>
    </Fragment>
  );
};

ReactDOM.createRoot(document.getElementById("root")).render(<App/>);
